const fs = require("node:fs");
const path = require("node:path");

const SKILL_BODY = "# demo-skill\n\nGenerated by AgentKit.\n";

function codexPaths(projectRoot) {
  return {
    skillDir: path.join(projectRoot, ".codex", "skills", "demo"),
    configFile: path.join(projectRoot, ".codex", "config.toml")
  };
}

function install(projectRoot, host) {
  if (host !== "codex") throw new Error("unsupported host: " + host);
  const { skillDir, configFile } = codexPaths(projectRoot);
  fs.mkdirSync(skillDir, { recursive: true });
  fs.writeFileSync(path.join(skillDir, "SKILL.md"), SKILL_BODY);
  let config = "";
  if (fs.existsSync(configFile)) config = fs.readFileSync(configFile, "utf8");
  if (!config.includes("[skills]")) config += "\n[skills]\nenabled = true\n";
  fs.writeFileSync(configFile, config);
}

function uninstall(projectRoot, host) {
  if (host !== "codex") throw new Error("unsupported host: " + host);
  const { skillDir, configFile } = codexPaths(projectRoot);
  fs.rmSync(skillDir, { recursive: true, force: true });
  if (fs.existsSync(configFile)) {
    const config = fs.readFileSync(configFile, "utf8").replace("\n[skills]\nenabled = true\n", "\n");
    fs.writeFileSync(configFile, config);
  }
}

module.exports = { install, uninstall };

