const test = require("node:test");
const assert = require("node:assert/strict");
const { mkdtempSync, existsSync, readFileSync } = require("node:fs");
const { tmpdir } = require("node:os");
const { join } = require("node:path");
const { install, uninstall } = require("../install.js");

test("install codex writes skill and config", () => {
  const root = mkdtempSync(join(tmpdir(), "ak-"));
  install(root, "codex");
  assert.equal(existsSync(join(root, ".codex", "skills", "demo", "SKILL.md")), true);
  assert.match(readFileSync(join(root, ".codex", "config.toml"), "utf8"), /\[skills\]/);
});

test("uninstall codex removes skill and config entry", () => {
  const root = mkdtempSync(join(tmpdir(), "ak-"));
  install(root, "codex");
  uninstall(root, "codex");
  assert.equal(existsSync(join(root, ".codex", "skills", "demo")), false);
  assert.doesNotMatch(readFileSync(join(root, ".codex", "config.toml"), "utf8"), /\[skills\]/);
});
